   if(string.IsNullOrWhiteSpace(path))throw new ArgumentException("Choose an export path");path=path.Replace('\\','/');string full=Path.GetFullPath(path),assets=Path.GetFullPath(Application.dataPath)+Path.DirectorySeparatorChar;if(!full.StartsWith(assets,StringComparison.OrdinalIgnoreCase)||!path.EndsWith(".prefab",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Body export must be a prefab inside this project's Assets folder");
path=AssetDatabase.GenerateUniqueAssetPath(path);string parent=Path.GetDirectoryName(path).Replace('\\','/');string folder=AssetDatabase.GenerateUniqueAssetPath(parent+"/"+Path.GetFileNameWithoutExtension(path)+"_Assets");AssetDatabase.CreateFolder(parent,Path.GetFileName(folder));var savedMesh=RebirthBodyGeneratorModel.Build(template,recipe);RebirthBodyHeadAssembly assembly=null;BodyDeepWoundAssembly deep=null;try{if(!string.IsNullOrEmpty(recipe.attachedHeadSettingsGuid)){assembly=RebirthBodyHeadAssembly.Build(savedMesh,recipe,false);UnityEngine.Object.DestroyImmediate(savedMesh);savedMesh=assembly.connection.body;}AssetDatabase.CreateAsset(savedMesh,folder+"/Body.asset");var skin=RebirthBodyGeneratorModel.Skin(recipe);skin.hideFlags=HideFlags.None;deep=RebirthBodyDeepWounds.Build(template,recipe,savedMesh,skin);if(skin.mainTexture!=null){string source=AssetDatabase.GetAssetPath(skin.mainTexture),target=folder+"/SkinFoundation.png";if(!AssetDatabase.CopyAsset(source,target))throw new IOException("Could not copy body skin source");skin.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(target);}if(skin.HasProperty("_RegionMask")){var mask=skin.GetTexture("_RegionMask");if(mask!=null){string maskTarget=folder+"/BodyPigmentRegions.png";if(!AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(mask),maskTarget))throw new IOException("Could not copy body pigment regions");skin.SetTexture("_RegionMask",AssetDatabase.LoadAssetAtPath<Texture2D>(maskTarget));}}var savedSurface=JsonUtility.FromJson<BodySurfaceSettings>(JsonUtility.ToJson(recipe.surface));RebirthBodySurface.Export(skin,savedSurface,folder);var savedDamage=JsonUtility.FromJson<BodyDamageSettings>(JsonUtility.ToJson(recipe.damage));RebirthBodyDamage.Export(skin,savedDamage,folder);RebirthFaceAppearance.CopyShader(skin,folder);AssetDatabase.CreateAsset(skin,folder+"/Skin.mat");var saved=JsonUtility.FromJson<BodyRecipe>(JsonUtility.ToJson(recipe));saved.damage=savedDamage;var root=new GameObject(recipe.name);try{root.AddComponent<MeshFilter>().sharedMesh=savedMesh;root.AddComponent<MeshRenderer>().sharedMaterial=skin;if(assembly!=null){assembly.ExportInto(root,skin,saved,folder);EditorUtility.SetDirty(savedMesh);EditorUtility.SetDirty(skin);}deep.Export(root,skin,saved,folder);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{UnityEngine.Object.DestroyImmediate(root);}saved.surface=savedSurface;saved.damage=savedDamage;RebirthAuthoredBody.Export(saved,folder);if(!string.IsNullOrEmpty(saved.bodyFoundationGuid)){string sourceFoundation=RebirthBodyGeneratorModel.FoundationPath(saved),targetFoundation=folder+"/BodySkinFoundation"+Path.GetExtension(sourceFoundation);if(!AssetDatabase.CopyAsset(sourceFoundation,targetFoundation))throw new IOException("Could not copy body skin foundation");saved.bodyFoundationGuid=AssetDatabase.AssetPathToGUID(targetFoundation);}if(skin.HasProperty("_RegionMask")&&skin.GetTexture("_RegionMask")!=null)saved.pigmentMaskGuid=AssetDatabase.AssetPathToGUID(folder+"/BodyPigmentRegions.png");if(skin.mainTexture!=null)saved.skinTextureGuid=AssetDatabase.AssetPathToGUID(folder+"/SkinFoundation.png");if(!string.IsNullOrEmpty(saved.skinReportGuid)){string sourceReport=AssetDatabase.GUIDToAssetPath(saved.skinReportGuid),targetReport=folder+"/SkinReport.json";if(!AssetDatabase.CopyAsset(sourceReport,targetReport))throw new IOException("Could not copy skin report");saved.skinReportGuid=AssetDatabase.AssetPathToGUID(targetReport);foreach(string filename in new[]{"BodySourceCoverage.png","FaceSkinDonorCoverage.png"}){string coverage=Path.Combine(Path.GetDirectoryName(sourceReport),filename);if(File.Exists(coverage)&&!AssetDatabase.CopyAsset(coverage,folder+"/"+filename))throw new IOException("Could not copy skin coverage");}}foreach(bool image in new[]{true,false}){string guid=image?saved.referenceGuid:saved.bodyImageReportGuid;if(string.IsNullOrEmpty(guid))continue;string source=AssetDatabase.GUIDToAssetPath(guid);if(!File.Exists(source))throw new IOException("Body reference/report asset is missing");string target=folder+"/"+(image?"Reference"+Path.GetExtension(source):"BodyImageReport.json");if(!AssetDatabase.CopyAsset(source,target))throw new IOException("Could not copy body reference provenance");if(image)saved.referenceGuid=AssetDatabase.AssetPathToGUID(target);else{saved.bodyImageReportGuid=AssetDatabase.AssetPathToGUID(target);foreach(string file in new[]{"PoseObservations.json","PersonMask.png","BodySilhouetteReport.json","AppearanceObservations.json","SemanticCategories.png","body-skinConfidence.png"}){string input=Path.Combine(Path.GetDirectoryName(source),file);if(File.Exists(input)){string output=folder+"/"+file;if(!AssetDatabase.CopyAsset(input,output))throw new IOException("Could not copy body observation: "+file);}}}}
   RebirthBodyGenerationJob.ExportReport(saved,folder);File.WriteAllText(folder+"/BodySettings.json",JsonUtility.ToJson(saved,true));AssetDatabase.ImportAsset(folder+"/BodySettings.json");AssetDatabase.SaveAssets();return "Exported "+path+". Authoring mesh assembly; rigging remains separate.";}finally{deep?.Dispose();if(assembly!=null){if(assembly.connection!=null&&AssetDatabase.Contains(assembly.connection.body))assembly.connection.body=null;assembly.Dispose();}if(savedMesh!=null&&!AssetDatabase.Contains(savedMesh))UnityEngine.Object.DestroyImmediate(savedMesh);}
  }
 }
